<template>
  <div class="foot-body-container">
    <div class="foot-body-container-title">添加场景</div>
    <div class="foot-body-container-scene" v-if="productId">
      <vr-upload
        ref="vrUpload"
        :cropImg="false"
        :autoUpload="true"
        mode="scene"
        :maxFileSize="50 * 1024 * 1024"
        :showFileList="true"
        :enableSort="true"
        :currentToolbarCode="currentToolbarCode"
        :action="uploadAction"
        :formData="{index: this.fileList.length - 1}"
        @onSuccess="onUploadSuccess"
        @onUpdate="onUpdate"
        @onRemove="onRemove"
      />
    </div>
    <update-scene-dialog ref="updateSceneDialog" @onSceneUpdate="() => {$emit('onSceneUpdate')}" />
  </div>
</template>
<script>
// eslint-disable-next-line no-unused-vars
import { appendProductScene, removeScene } from '@/api/vr'
import VrUpload from '@/components/VrUpload.vue'
export default {
  props: {
    currentToolbarCode: String,
    productId: {
    type: [String, Number], // 允许多种类型
    required: true,
  },
    scenes: {
      type: Array,
      default() {
        return []
      }
    }
  },
  computed: {
    uploadAction() {
      return appendProductScene(this.productId)
    }
  },
  data() {
    return {
      dialogImageUrl: '',
      dialogVisible: false,
      fileList: [],
      key: 0
    }
  },
  created() {},
  mounted() {},
  components: {
    VrUpload,
    UpdateSceneDialog: () =>
      import('../../views/form/UpdateSceneFormDialog.vue')
  },
  methods: {
    initScenes(fileList) {
      this.fileList = fileList
      this.$refs.vrUpload.initFileList(fileList)
    },
    removeFile(file, fileList) {
      return fileList.filter(item => {
        return item.id !== file.id
      })
    },
    handlePictureCardPreview(file) {
      this.dialogImageUrl = file.url
      this.dialogVisible = true
    },
    onUploadSuccess(file) {
      // console.log('场景上传成功后调用创建作品新场景接口:', file, this.key, this.fileList)
      // 参考：https://blog.csdn.net/lpw_cn/article/details/90404117
      this.fileList.push(file)
      this.$refs.vrUpload.key += 1
      this.$refs.vrUpload.initFileList(this.fileList)
      this.$emit('onSceneUpdate', this.fileList, null, 'add')
    },
    onUpdate(file) {
      this.$refs.updateSceneDialog.open(this.productId, file)
    },
    // eslint-disable-next-line no-unused-vars
    async onRemove(file, fileList) {
      console.log('正在删除场景:', this.currentToolbarCode)
      await removeScene(file.id)
      this.$refs.vrUpload.key -= 1
      this.fileList = this.removeFile(file, fileList)
      this.$refs.vrUpload.initFileList(this.fileList)
      this.$emit('onSceneUpdate', this.fileList)
    }
  }
}
</script>
